import type { StatusMeta } from './status';
import { timeAgo } from './time';

/**
 * How an ambulance's position is described. No GPS receiver is integrated with JIVA: a position is set
 * manually by the crew, generated by a demo tool, or reported without a source. Only a DEVICE_GPS position
 * may ever be called "GPS".
 */
export type PositionSource = 'DEVICE_GPS' | 'MANUAL' | 'SIMULATED';

export function positionSource(source?: string): StatusMeta {
  switch (source) {
    case 'DEVICE_GPS':
      return { label: 'GPS', tone: 'ok', icon: 'navigation', hint: "Position from the unit's GPS receiver." };
    case 'MANUAL':
      return { label: 'Set by the crew', tone: 'neutral', icon: 'pin', hint: 'The crew set this position in the app. JIVA receives no GPS from this unit.' };
    case 'SIMULATED':
      return { label: 'Simulated position', tone: 'info', icon: 'navigation', hint: 'Generated by a demo tool. Not a real location.' };
    default:
      return { label: 'Position, source not stated', tone: 'neutral', icon: 'pin', hint: 'This position was reported without saying where it came from. It is not presented as GPS.' };
  }
}

/** "Set by the crew · 2 min ago", "Simulated position · just now", "No position update since dispatch". */
export function positionUpdateText(a: { locationAsOf?: string; locationSource?: string } | null | undefined, now: number, whenNone = 'No position update yet'): string {
  if (!a?.locationAsOf) return whenNone;
  return `${positionSource(a.locationSource).label} · ${timeAgo(a.locationAsOf, now)}`;
}
